<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; Security::requireRole(['administrador']);$rows=db()->query('SELECT l.*,u.nome usuario FROM logs l LEFT JOIN usuarios u ON u.id=l.usuario_id ORDER BY l.id DESC LIMIT 200')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auditoria</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><h1>Logs de auditoria</h1><a href="dashboard.php">← Dashboard</a><table class="table table-sm mt-4"><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Tabela</th><th>ID</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['data_hora'])?></td><td><?=Security::e($r['usuario']??'-')?></td><td><?=Security::e($r['acao'])?></td><td><?=Security::e($r['tabela_afetada'])?></td><td><?=Security::e((string)$r['registro_id'])?></td><td><?=Security::e($r['ip'])?></td></tr><?php endforeach;?></tbody></table></div></body></html>
